      const effect = (() => {
        const juedou = new lib.element.VCard({ name: "juedou" });
        const juedouEff = get.effect(target, juedou, player2, player2);
        const loseEff = get.effect(player2, { name: "losehp" }, player2, player2);
        if (!player2.canUse(juedou, target, false)) {
          return loseEff;
        }
        return juedouEff + (juedouEff >= 0 ? 0 : loseEff);
      })();
