  mbjiejian: {
    audio: 3,
    trigger: {
      player: "phaseZhunbeiBegin"
    },
    filter(event, player2) {
      return player2.countCards("h");
    },
    async cost(event, trigger, player2) {
      if (_status.connectMode) {
        game.broadcastAll(function() {
          _status.noclearcountdown = true;
        });
      }
      const give_map = {};
      let used = [];
      do {
        const result = await player2.chooseCardTarget({
          filterCard(card2) {
            return get.itemtype(card2) == "card" && !card2.hasGaintag("mbjiejian_tag");
          },
          filterTarget: lib.filter.notMe,
          selectCard: [1, Infinity],
          prompt: used.length ? "是否继续分配手牌？" : get.prompt(event.skill),
          prompt2: "将任意张手牌交给一名其他角色",
          allowChooseAll: true,
          ai1(card2) {
            if (!ui.selected.cards.length) {
              return 8 - get.value(card2);
            }
            return 0;
          },
          ai2(target) {
            let player3 = _status.event.player, card2 = ui.selected.cards[0];
            let val = get.value(card2), att = get.attitude(player3, target);
            if (val <= 4) {
              if (get.event().used.includes(target)) {
                return 0;
              }
              return 1 / target.getUseValue(card2);
            }
            return att * (target.getUseValue(card2) + 4);
          }
        }).set("used", used).forResult();
        if (result?.bool && result.targets?.length) {
          const id = result.targets[0].playerid, map = give_map;
          if (!map[id]) {
            map[id] = [];
          }
          map[id].addArray(result.cards);
          player2.addGaintag(result.cards, "mbjiejian_tag");
          used.addArray(result.targets);
        }
        break;
      } while (player2.countCards("h"));
      if (_status.connectMode) {
        game.broadcastAll(function() {
          delete _status.noclearcountdown;
          game.stopCountChoose();
        });
      }
      const list = [], targets2 = [];
      for (const i in give_map) {
        const source = (_status.connectMode ? lib.playerOL : game.playerMap)[i];
        player2.line(source, "green");
        if (player2 !== source && (get.mode() !== "identity" || player2.identity !== "nei")) {
          player2.addExpose(0.2);
        }
        targets2.push(source);
        list.push([source, give_map[i]]);
      }
      event.result = {
        bool: list.length > 0,
        targets: targets2,
        cost_data: list
      };
    },
    logAudio: () => 1,
    async content(event, trigger, player2) {
      const list = event.cost_data;
      await game.loseAsync({
        gain_list: list,
        player: player2,
        cards: list.map((i) => i[1]).flat(),
        giver: player2,
        animate: "giveAuto"
      }).setContent("gaincardMultiple");
      for (let target of event.targets) {
        let num = target.hp - target.countMark("mbjiejian_mark");
        target.addMark("mbjiejian_mark", num, false);
      }
    },
    group: ["mbjiejian_liuli", "mbjiejian_remove"],
    subSkill: {
      used: {
        charlotte: true,
        onremove: true
      },
      liuli: {
        audio: "mbjiejian2.mp3",
        trigger: { global: "useCardToTarget" },
        filter(event, player2) {
          if (event.player == player2 || get.type(event.card) == "equip") {
            return false;
          }
          if (!event.targets || event.targets.length != 1) {
            return false;
          }
          if (!event.targets[0].hasMark("mbjiejian_mark")) {
            return false;
          }
          return !player2.getStorage("mbjiejian_used").includes(event.target);
        },
        prompt2(event, player2) {
          return `将${get.translation(event.card)}转移给自己`;
        },
        check(event, player2) {
          const target = event.targets[0];
          const card2 = event.card;
          const source = event.player;
          const eff1 = get.effect(target, card2, source, player2);
          if (eff1 > 0) {
            return false;
          }
          const eff2 = get.effect(player2, card2, source, player2) + get.effect(player2, { name: "draw" }, player2, player2);
          if (eff2 >= eff1) {
            return true;
          }
          let save = false;
          if (get.attitude(player2, target) > 2) {
            if (card2.name == "sha") {
              if (player2.hasShan() || player2.getEquip(2) || target.hp == 1 || player2.hp > target.hp + 1) {
                if (!target.hasShan() || target.countCards("h") < player2.countCards("h")) {
                  save = true;
                }
              }
            } else if (card2.name == "juedou" && target.hp == 1) {
              save = true;
            } else if (card2.name == "shunshou" && get.attitude(player2, source) < 0 && get.attitude(source, target) < 0) {
              save = true;
            }
          }
          return save;
        },
        logTarget: "target",
        async content(event, trigger, player2) {
          player2.addTempSkill("mbjiejian_used");
          player2.markAuto("mbjiejian_used", event.targets);
          const evt = trigger.getParent();
          evt.triggeredTargets2.removeArray(event.targets);
          evt.targets.removeArray(event.targets);
          if (lib.filter.targetEnabled2(trigger.card, trigger.player, player2)) {
            evt.targets.push(player2);
          }
          await player2.draw();
        }
      },
      remove: {
        audio: "mbjiejian3.mp3",
        trigger: { global: "phaseEnd" },
        forced: true,
        filter(event, player2) {
          return event.player.hasMark("mbjiejian_mark");
        },
        logTarget: "player",
        async content(event, trigger, player2) {
          const target = event.targets[0], num = target.countMark("mbjiejian_mark");
          target.removeMark("mbjiejian_mark", num, false);
          if (target.hp >= num) {
            await player2.draw(2);
          }
        }
      },
      mark: { intro: { content: "获得“节谏”时的体力值：$" } }
    }
  },
