  mbjuejin: {
    audio: 2,
    persevereSkill: true,
    enable: "phaseUse",
    limited: true,
    skillAnimation: true,
    animationColor: "thunder",
    filterCard: () => false,
    selectCard: [-1, -2],
    filterTarget: true,
    selectTarget: -1,
    multiline: true,
    async contentBefore(event, trigger, player2) {
      game.broadcastAll(() => {
        _status.tempMusic = "effect_caomaoBJM";
        game.playBackgroundMusic();
      });
      player2.changeSkin({ characterName: "mb_caomao" }, "mb_caomao_shadow");
      player2.awakenSkill(event.skill);
    },
    async content(event, trigger, player2) {
      const target = event.target;
      let delt = target.getHp() - 1, num = Math.abs(delt);
      if (delt != 0) {
        if (delt > 0) {
          const next = target.changeHp(-delt);
          next._triggered = null;
          await next;
        } else {
          num = 1 - target.getHp(true);
          await target.recover(num);
        }
      }
      if (delt > 0) {
        await target.changeHujia(num + (player2 == target ? 2 : 0), null, true);
      } else if (player2 == target) {
        await target.changeHujia(2, null, true);
      }
    },
    async contentAfter(event, trigger, player2) {
      game.addGlobalSkill("mbjuejin_xiangsicunwei");
      player2.$fullscreenpop("向死存魏！", "thunder");
      const cards2 = ["cardPile", "discardPile"].map((pos) => Array.from(ui[pos].childNodes)).flat();
      const filter = (card2) => ["shan", "tao", "jiu"].includes(card2.name);
      const cardx = cards2.filter(filter);
      if (cardx.length) {
        await game.cardsGotoSpecial(cardx);
        game.log(cardx, "被移出了游戏");
      }
      for (const target of game.filterPlayer()) {
        const sishis = target.getCards("hej", filter);
        if (sishis.length) {
          target.$throw(sishis);
          game.log(sishis, "被移出了游戏");
          await target.lose(sishis, ui.special);
        }
      }
    },
    ai: {
      order: 0.1,
      result: {
        player(player2) {
          let eff = 1;
          game.countPlayer((current) => {
            const att = get.attitude(player2, current), num = Math.abs(current.getHp(true) - 1);
            const delt = Math.max(0, num + current.hujia - 5);
            eff -= att * delt;
          });
          return eff > 0 ? 1 : 0;
        }
      }
    },
    subSkill: {
      xiangsicunwei: {
        trigger: { global: ["loseAfter", "equipAfter", "loseAsyncAfter", "cardsDiscardAfter"] },
        forced: true,
        silent: true,
        firstDo: true,
        filter(event, player2) {
          const nameList = ["shan", "tao", "jiu"];
          return event.getd().some((card2) => {
            return nameList.includes(get.name(card2, false)) && get.position(card2, true) === "d";
          });
        },
        async content(event, trigger, player2) {
          const nameList = ["shan", "tao", "jiu"];
          const cards2 = trigger.getd().filter((card2) => {
            return nameList.includes(get.name(card2, false)) && get.position(card2, true) === "d";
          });
          await game.cardsGotoSpecial(cards2);
          game.log(cards2, "被移出了游戏");
        }
      }
    }
  },
