    getNum(player2, event) {
      let num = 3;
      const history = game.getAllGlobalHistory("everything");
      let index;
      for (let i = history.length - 1; i >= 0; i--) {
        const evt = history[i];
        if (evt.name == "jieyu" && evt.player == player2) {
          if (!event || evt != event) {
            index = i;
            break;
          }
        }
      }
      if (index) {
        for (let i = index + 1; i < history.length; i++) {
          const evt = history[i];
          if (evt.name == "useCard" && evt.player != player2 && evt.targets?.includes(player2) && get.is.damageCard(evt.card)) {
            num--;
            if (num == 1) {
              break;
            }
          }
        }
      }
      return num;
    }
