  scspicai: {
    audio: 1,
    enable: "phaseUse",
    usable: 1,
    manualConfirm: true,
    frequent: true,
    async content(event, trigger, player2) {
      event.cards = [];
      event.suits = [];
      event.again = true;
      while (event.again) {
        event.again = false;
        await player2.judge((result2) => {
          let evt = _status.event.getParent("scspicai");
          if (evt?.suits?.includes(get.suit(result2))) {
            return 0;
          }
          return 1;
        }).set("callback", lib.skill.scspicai.callback).set("judge2", (result2) => result2.bool);
      }
      const cards2 = event.cards.filterInD();
      if (!cards2.length) {
        return;
      }
      const result = await player2.chooseTarget("将" + get.translation(cards2) + "交给一名角色", true).set("ai", function(target2) {
        var player3 = _status.event.player;
        var att = get.attitude(player3, target2) / Math.sqrt(1 + target2.countCards("h"));
        if (target2.hasSkillTag("nogain")) {
          att /= 10;
        }
        return att;
      }).forResult();
      if (!result.bool) {
        return;
      }
      const target = result.targets[0];
      player2.line(target, "green");
      const next = target.gain(cards2, "gain2");
      next.giver = player2;
      await next;
    },
    async callback(event, trigger, player2) {
      const evt = event.getParent(2);
      event.getParent().orderingCards.remove(event.judgeResult.card);
      evt.cards.push(event.judgeResult.card);
      if (event.getParent().result.bool) {
        evt.suits.push(event.getParent().result.suit);
        const result = await player2.chooseBool("是否继续发动【庀材】？").set("frequentSkill", "scspicai").forResult();
        if (result.bool) {
          event.getParent(2).again = true;
        }
      } else {
        return;
      }
    },
    ai: {
      order: 9,
      result: {
        player: 1
      }
    }
  },
