  //高望
  scsanruo: {
    audio: 1,
    enable: ["chooseToUse", "chooseToRespond"],
    prompt: "将一张♥牌当做桃，♦牌当做火杀，♣牌当做闪，♠牌当做无懈可击使用或打出",
    viewAs(cards2, player2) {
      var name = false;
      var nature = null;
      switch (get.suit(cards2[0], player2)) {
        case "club":
          name = "shan";
          break;
        case "diamond":
          name = "sha";
          nature = "fire";
          break;
        case "spade":
          name = "wuxie";
          break;
        case "heart":
          name = "tao";
          break;
      }
      if (name) {
        return { name, nature };
      }
      return null;
    },
    check(card2) {
      var player2 = _status.event.player;
      if (_status.event.type == "phase") {
        var max = 0;
        var name2;
        var list = ["sha", "tao"];
        var map = { sha: "diamond", tao: "heart" };
        for (var i = 0; i < list.length; i++) {
          var name = list[i];
          if (player2.countCards("hes", function(card3) {
            return (name != "sha" || get.value(card3) < 5) && get.suit(card3, player2) == map[name];
          }) > 0 && player2.getUseValue({ name, nature: name == "sha" ? "fire" : null }) > 0) {
            var temp = get.order({ name, nature: name == "sha" ? "fire" : null });
            if (temp > max) {
              max = temp;
              name2 = map[name];
            }
          }
        }
        if (name2 == get.suit(card2, player2)) {
          return name2 == "diamond" ? 5 - get.value(card2) : 20 - get.value(card2);
        }
        return 0;
      }
      return 1;
    },
    position: "hes",
    filterCard(card2, player2, event) {
      event = event || _status.event;
      var filter = event._backup.filterCard;
      var name = get.suit(card2, player2);
      if (name == "club" && filter({ name: "shan", cards: [card2] }, player2, event)) {
        return true;
      }
      if (name == "diamond" && filter({ name: "sha", cards: [card2], nature: "fire" }, player2, event)) {
        return true;
      }
      if (name == "spade" && filter({ name: "wuxie", cards: [card2] }, player2, event)) {
        return true;
      }
      if (name == "heart" && filter({ name: "tao", cards: [card2] }, player2, event)) {
        return true;
      }
      return false;
    },
    filter(event, player2) {
      var filter = event.filterCard;
      if (filter(get.autoViewAs({ name: "sha", nature: "fire" }, "unsure"), player2, event) && player2.countCards("hes", { suit: "diamond" })) {
        return true;
      }
      if (filter(get.autoViewAs({ name: "shan" }, "unsure"), player2, event) && player2.countCards("hes", { suit: "club" })) {
        return true;
      }
      if (filter(get.autoViewAs({ name: "tao" }, "unsure"), player2, event) && player2.countCards("hes", { suit: "heart" })) {
        return true;
      }
      if (filter(get.autoViewAs({ name: "wuxie" }, "unsure"), player2, event) && player2.countCards("hes", { suit: "spade" })) {
        return true;
      }
      return false;
    },
    async precontent(event, trigger, player2) {
      player2.addTempSkill("scsanruo_effect");
    },
    ai: {
      respondSha: true,
      respondShan: true,
      skillTagFilter(player2, tag) {
        var name;
        switch (tag) {
          case "respondSha":
            name = "diamond";
            break;
          case "respondShan":
            name = "club";
            break;
          case "save":
            name = "heart";
            break;
        }
        if (!player2.countCards("hes", { suit: name })) {
          return false;
        }
      },
      order(item, player2) {
        if (player2 && _status.event.type == "phase") {
          var max = 0;
          var list = ["sha", "tao"];
          var map = { sha: "diamond", tao: "heart" };
          for (var i = 0; i < list.length; i++) {
            var name = list[i];
            if (player2.countCards("hes", function(card2) {
              return (name != "sha" || get.value(card2) < 5) && get.suit(card2, player2) == map[name];
            }) > 0 && player2.getUseValue({
              name,
              nature: name == "sha" ? "fire" : null
            }) > 0) {
              var temp = get.order({
                name,
                nature: name == "sha" ? "fire" : null
              });
              if (temp > max) {
                max = temp;
              }
            }
          }
          max /= 1.1;
          return max;
        }
        return 2;
      }
    },
    hiddenCard(player2, name) {
      if (name == "wuxie" && _status.connectMode && player2.countCards("hes") > 0) {
        return true;
      }
      if (name == "wuxie") {
        return player2.countCards("hes", { suit: "spade" }) > 0;
      }
      if (name == "tao") {
        return player2.countCards("hes", { suit: "heart" }) > 0;
      }
    },
    subSkill: {
      effect: {
        audio: "scsanruo",
        trigger: {
          player: ["useCard", "respond"]
        },
        filter(event, player2) {
          return event.skill == "scsanruo";
        },
        direct: true,
        forced: true,
        charlotte: true,
        async content(event, trigger, player2) {
          var name = trigger.card.name;
          var next = game.createEvent("scsanruo_" + name);
          next.player = player2;
          await next.setContent(lib.skill.scsanruo_effect[name == "shan" ? "sha" : name] || function() {
          });
        },
        async sha(event, trigger, player2) {
          var trigger = event.getParent().getTrigger();
          var target;
          if (trigger.name == "useCard") {
            target = lib.skill.chongzhen.logTarget(trigger, player2);
          } else {
            target = trigger.source;
          }
          if (!target || !target.countGainableCards(player2, "he")) {
            return;
          }
          const result = await player2.chooseBool(get.prompt("scsanruo_effect", target), "获得该角色的一张牌").set("ai", () => {
            return _status.event.goon;
          }).set("goon", get.attitude(player2, target) < 1).forResult();
          if (result.bool) {
            player2.logSkill("scsanruo_effect", target);
            await player2.gainPlayerCard(target, "he", true);
          }
        },
        async tao(event, trigger, player2) {
          const result = await player2.chooseTarget(get.prompt("scsanruo"), "获得一名其他角色的一张牌", (card2, player3, target2) => {
            return target2.countGainableCards(player3, "he") && target2 != player3;
          }).set("ai", (target2) => {
            return 1 - get.attitude(_status.event.player, target2);
          }).forResult();
          if (result.bool) {
            var target = result.targets[0];
            player2.logSkill("scsanruo_effect", target);
            await player2.gainPlayerCard(target, "he", true);
          }
        },
        async wuxie(event, trigger, player2) {
          var trigger = event.getParent().getTrigger();
          if (!trigger.respondTo) {
            return;
          }
          var target = trigger.respondTo[0];
          if (!target || !target.countGainableCards(player2, player2 == target ? "e" : "he")) {
            return;
          }
          const result = await player2.chooseBool(get.prompt("scsanruo_effect", target), "获得该角色的一张牌").set("ai", () => {
            return _status.event.goon;
          }).set("goon", get.attitude(player2, target) < 1).forResult();
          if (result.bool) {
            player2.logSkill("scsanruo_effect", target);
            await player2.gainPlayerCard(target, player2 == target ? "e" : "he", true);
          }
        }
      }
    }
  },
