      canvas.style.height = "414px";
      canvas.style.left = "calc(50% - 141px)";
      canvas.style.top = "calc(50% - 200px)";
      canvas.width = 276;
      canvas.height = 414;
      canvas.style.border = "3px solid";
      const RAD = Math.PI / 180;
      const ctx = canvas.getContext("2d");
      let frames = 0;
      let dx = 0.1;
