  tongqu2: {
    trigger: { player: "phaseDrawEnd" },
    forced: true,
    silent: true,
    sourceSkill: "tongqu",
    filter(event, player2) {
      var bool = game.hasPlayer(function(current) {
        return current != player2 && current.hasMark("tongqu");
      });
      return player2.countCards("he", function(card2) {
        if (bool) {
          return true;
        }
        return lib.filter.cardDiscardable(card2, player2);
      }) > 0;
    },
    async content(event, trigger, player2) {
      const result = await player2.chooseCardTarget({
        forced: true,
        position: "he",
        filterCard: true,
        filterTarget(card2, player3, target) {
          return player3 != target && target.hasMark("tongqu");
        },
        selectTarget() {
          if (ui.selected.cards.length && !lib.filter.cardDiscardable(ui.selected.cards[0], _status.event.player)) {
            return [1, 1];
          }
          return [0, 1];
        },
        prompt: "弃置一张牌，或将一张牌交给一名有“渠”的其他角色",
        ai1(card2) {
          var player3 = _status.event.player;
          if (get.name(card2) == "du") {
            return 20;
          }
          if (get.position(card2) == "e" && get.value(card2) <= 0) {
            return 14;
          }
          if (get.position(card2) == "h" && game.hasPlayer(function(current) {
            return current != player3 && current.hasMark("tongqu") && get.attitude(player3, current) > 0 && current.getUseValue(card2) > player3.getUseValue(card2) && current.getUseValue(card2) > player3.getUseValue(card2);
          })) {
            return 12;
          }
          if (game.hasPlayer(function(current) {
            return current != player3 && current.hasMark("tongqu") && get.attitude(player3, current) > 0;
          })) {
            if (card2.name == "wuxie") {
              return 11;
            }
            if (card2.name == "shan" && player3.countCards("h", "shan") > 1) {
              return 9;
            }
          }
          return 6 / Math.max(1, get.value(card2));
        },
        ai2(target) {
          var player3 = _status.event.player;
          var card2 = ui.selected.cards[0];
          var att = get.attitude(player3, target);
          if (card2.name == "du") {
            return -6 * att;
          }
          if (att > 0) {
            if (get.position(card2) == "h" && target.getUseValue(card2) > player3.getUseValue(card2)) {
              return 4 * att;
            }
            if (target.hasUseTarget(card2)) {
              return 2 * att;
            }
            return 1.2 * att;
          }
          return 0;
        }
      }).forResult();
      if (!result.bool) {
        return;
      }
      if (result.targets.length) {
        const target = result.targets[0];
        await player2.give(result.cards, target);
        const card2 = result.cards[0];
        if (target.getCards("h").includes(card2) && get.type(card2) == "equip") {
          await target.chooseUseTarget(card2, true).forResult();
        }
      } else {
        await player2.discard(result.cards);
      }
    }
  },
