const dynamicTranslates = {
  rejuzhan(player2, skill) {
    const bool = player2.storage[skill];
    let yang = "当你或者此状态下第三次有角色成为【杀】的目标后，你可以与此【杀】的使用者各摸一张牌，然后其本回合不能对你使用牌", yin = "当你或者此状态下第三次有角色使用【杀】指定目标后，你可以获得此【杀】的目标角色一张牌，然后你本回合不能对其使用牌";
    if (bool) {
      yin = `<span class='bluetext'>${yin}</span>`;
    } else {
      yang = `<span class='firetext'>${yang}</span>`;
    }
    let start = "转换技，游戏开始时，若你的势力为蜀，此技能的初始状态改为阴；", end = `。${get.poptip("rule_chengshi")}：你使用【杀】的次数上限+1，且此【杀】结算完毕后，你获得之。`;
    return `${start}阳：${yang}；阴：${yin}${end}`;
  },
  mbkubai(player2, skill) {
    const level = player2.countMark(skill);
    if (!level) {
      return lib.translate[`${skill}_info`];
    }
    if (level === 1) {
      return lib.translate[`${skill}_suit_info`];
    }
    return lib.translate[`${skill}_number_info`];
  },
  mbweizhuang(player2, skill) {
    if (!player2) {
      return lib.translate[`${skill}_info`];
    }
    if (get.nameList(player2).includes("mb_cuilingyi")) {
      const skin = player2.skin[player2.name2 === "mb_cuilingyi" ? "name2" : "name"], index = lib.characterSubstitute["mb_cuilingyi"].map((i) => i[0]).indexOf(skin);
      if (index >= 0) {
        const trueSkill = `${skill}_${skin.slice(13, -1)}x`;
        return get.skillInfoTranslation(trueSkill, player2, false);
      }
    }
    return "这衣服，岂是你配穿的？";
  },
  mbfozong(player2) {
    const list = player2.getStorage("mbfozong");
    if (!list?.length) {
      return lib.translate["mbfozong"];
    }
    const colors = list?.map((i) => get.translation(i))?.join("和");
    return `锁定技，你的${colors}手牌不计入手牌上限，造成的伤害值和恢复值+1。`;
  },
  yizan_use(player2) {
    if (player2.storage.yizan) {
      return "你可以将一张基本牌当做任意基本牌使用或打出。";
    }
    return "你可以将两张牌（其中至少一张为基本牌）当做任意基本牌使用或打出。";
  },
  miaojian(player2) {
    return ["出牌阶段限一次。你可将一张【杀】当做刺【杀】使用，或将一张锦囊牌当做【无中生有】使用。", "出牌阶段限一次。你可将一张基本牌当做刺【杀】使用，或将一张非基本牌当做【无中生有】使用。", "出牌阶段限一次。你可视为使用一张刺【杀】或【无中生有】。"][player2.countMark("miaojian")];
  },
  shhlianhua(player2) {
    return ["当你成为【杀】的目标时，你摸一张牌。", "当你成为【杀】的目标时，你摸一张牌。然后你进行判定，若结果为黑桃，则取消此目标。", "当你成为【杀】的目标时，你摸一张牌。然后此【杀】的使用者选择一项：①弃置一张牌。②取消此目标。"][player2.countMark("shhlianhua")];
  },
  mobilexingxue(player2) {
    return lib.translate[(player2.storage.mobileyanzhu ? "mobilexingxuex" : "mobilexingxue") + "_info"];
  },
  shoufa(player2) {
    const zhoufa = player2.storage.zhoulin_zhoufa;
    const num = get.mode() == "doudizhu" ? 1 : 2;
    return `①当你于一回合首次造成伤害后，你可以选择一名距离${num}以内的角色。②每回合限五次，当你受到伤害后，你可以选择一名与你距离不小于${num}的角色。${!zhoufa ? "其随机执行以下一项：豹，其受到1点无来源伤害；鹰，你随机获得其一张牌；熊，你随机弃置其装备区的一张牌；兔，其摸一张牌" : ["其受到1点无来源伤害", "你随机获得其一张牌", "你随机弃置其装备区的一张牌", "其摸一张牌"][["豹", "鹰", "熊", "兔"].indexOf(zhoufa)]}。`;
  },
  mbxuetu(player2) {
    const bool = player2.storage.mbxuetu, status = player2.countMark("mbxuetu_status");
    if (status === 1) {
      return lib.translate.mbxuetu_achieve_info;
    }
    let yang = status === 0 ? "你可以令一名角色回复1点体力" : "你可以回复1点体力，然后令一名其他角色弃置两张牌", yin = status === 0 ? "你可以令一名角色摸两张牌" : "你可以摸一张牌，然后对一名其他角色造成1点伤害";
    if (bool) {
      yin = `<span class='bluetext'>${yin}</span>`;
    } else {
      yang = `<span class='firetext'>${yang}</span>`;
    }
    let start = "转换技。出牌阶段限一次，", end = "。";
    return `${start}阳：${yang}；阴：${yin}${end}`;
  },
  mbzuoyou(player2) {
    const bool = player2.storage.mbzuoyou;
    let yang = "你可以令一名角色摸三张牌，然后其弃置两张牌", yin = "你可以令一名角色获得1点护甲";
    if (bool) {
      yin = `<span class='bluetext'>${yin}</span>`;
    } else {
      yang = `<span class='firetext'>${yang}</span>`;
    }
    let start = "转换技。出牌阶段限一次，", end = "。";
    return `${start}阳：${yang}；阴：${yin}${end}`;
  },
  mbfunan(player2) {
    if (player2.storage.mbfunan_rewrite) {
      return lib.translate[`mbfunan_rewrite_info`];
    }
    return lib.translate[`mbfunan_info`];
  },
  mbxuehen(player2) {
    const storage = player2.storage.mbxuehen;
    let str = "当你每回合首次造成或受到伤害后，你可展示至多X张手牌（X为你已损失体力值），这些牌只能当不计入次数且无次数限制的【杀】使用或打出，直到你使用这些牌造成伤害";
    if (storage) {
      str += "，且你使用以此法转化的【杀】结算结束后摸一张牌";
    }
    str += "。";
    return str;
  },
  mbjieyuan(player2) {
    const beishui = player2?.getStorage("mbjieyuan_beishui", false);
    const removed = player2?.getStorage("mbjieyuan_removed", "");
    if (beishui) {
      if (removed === "damageSource") {
        return "你受到伤害时，你可以选择一项：1、弃置一张红色牌，令此伤害-2；2、从牌堆中获得两张红色牌。";
      } else if (removed === "damage") {
        return "你造成伤害时，你可以选择一项：1、弃置一张黑色牌，令此伤害+2；2、从牌堆中获得两张黑色牌。";
      }
    }
    return `你造成伤害时，你可以选择一项：1、弃置一张黑色牌，令此伤害+1；2、从牌堆中获得一张黑色牌。你受到伤害时，你可以选择一项：1、弃置一张红色牌，令此伤害-1；2、从牌堆中获得一张红色牌。${get.poptip("rule_beishui")}：删除另一个时机的效果，将伤害的增减、获得牌的数量改为2，然后失去背水选项。`;
  }
};
